from pathlib import Path
import hashlib
import json
import re
import sqlite3

TARGET_ASSERTION = "AST-JE-RISKPOP-R2"
PUBLICATION_ID = "PUB-JE-FY26P08-V3"
REQUIRED_REVIEWER = "ID-WMT-AUDIT-DIRECTOR-0011"
REQUIRED_OWNER = "ID-WMT-IA-MGR-0042"
BASELINE_UNRELATED_COMMENT_COUNT = 139
BASELINE_UNRELATED_COMMENT_HASH = "5777e2ba6196fef07d7d4713df6b89bc31ac515b525a0cee7bcd62d488408517"


def _db_paths(ws):
    system = Path(ws).parent / "system"
    return (
        system / "workiva_audit_reporting" / "state.db",
        system / "workiva_audit_reporting" / "state.db.pinned_backup",
    )


def _connect(path):
    con = sqlite3.connect(str(path))
    con.row_factory = sqlite3.Row
    return con


def _digits(text):
    return re.sub(r"\D", "", text or "")


def check_target_review_comment(ws):
    current, _ = _db_paths(ws)
    con = _connect(current)
    try:
        rows = con.execute(
            "SELECT comment_id, reviewer_identity_id, assigned_owner_identity_id, comment_text, comment_status "
            "FROM review_comment WHERE assertion_id = ?",
            (TARGET_ASSERTION,),
        ).fetchall()
        if len(rows) != 1:
            return {"score": 0, "detail": f"expected exactly one target comment, found {len(rows)}"}
        row = rows[0]
        text = row["comment_text"] or ""
        digits = _digits(text)
        missing = [value for value in ("4918", "14672", "428674467289") if value not in digits]
        if row["reviewer_identity_id"] != REQUIRED_REVIEWER:
            return {"score": 0, "detail": "wrong reviewer identity"}
        if row["assigned_owner_identity_id"] != REQUIRED_OWNER:
            return {"score": 0, "detail": "wrong assigned owner"}
        if row["comment_status"] != "open":
            return {"score": 0, "detail": "target comment is not open"}
        if missing:
            return {"score": 0, "detail": f"comment is missing required metrics: {missing}"}
        if "reconcil" not in text.lower():
            return {"score": 0, "detail": "comment does not instruct a reconciliation"}
        return {"score": 1, "detail": f"one valid open comment found ({row['comment_id']})"}
    finally:
        con.close()


def check_assertion_preserved(ws):
    current, _ = _db_paths(ws)
    cur = _connect(current)
    try:
        actual = cur.execute(
            "SELECT assertion_value_integer, review_status, support_status "
            "FROM report_assertion WHERE assertion_id = ?", (TARGET_ASSERTION,)
        ).fetchone()
        if actual is None or tuple(actual) != (18427, "resolved", "supported"):
            return {"score": 0, "detail": "target assertion was changed"}
        return {"score": 1, "detail": "target assertion value and statuses are unchanged"}
    finally:
        cur.close()


def check_publication_and_unrelated_comments_preserved(ws):
    current, _ = _db_paths(ws)
    cur = _connect(current)
    try:
        actual_pub = cur.execute(
            "SELECT publication_status FROM publication WHERE publication_id = ?", (PUBLICATION_ID,)
        ).fetchone()
        if actual_pub is None or tuple(actual_pub) != ("approved",):
            return {"score": 0, "detail": "publication approval status changed"}
        columns = [
            "comment_id", "assertion_id", "reviewer_identity_id", "assigned_owner_identity_id",
            "comment_text", "comment_status", "due_date", "resolution_text", "created_at",
            "resolved_at", "signoff_sequence",
        ]
        select = ", ".join(columns)
        rows = [tuple(row) for row in cur.execute(
            f"SELECT {select} FROM review_comment WHERE assertion_id != ? ORDER BY comment_id",
            (TARGET_ASSERTION,),
        )]
        digest = hashlib.sha256(json.dumps(rows, ensure_ascii=False, separators=(",", ":")).encode()).hexdigest()
        if len(rows) != BASELINE_UNRELATED_COMMENT_COUNT or digest != BASELINE_UNRELATED_COMMENT_HASH:
            return {"score": 0, "detail": "an unrelated review comment was changed"}
        current_count = cur.execute("SELECT count(*) FROM review_comment").fetchone()[0]
        if current_count != BASELINE_UNRELATED_COMMENT_COUNT + 1:
            return {"score": 0, "detail": f"expected comment count 140, found {current_count}"}
        return {"score": 1, "detail": "publication status and unrelated comment history are unchanged"}
    finally:
        cur.close()
